기존 isHost 로직 아래에 else 조건 추가:

기존: {isHost && (<><Separator /><section>주최자 액션...</section></>)}

변경:
{isHost ? (
  <><Separator /><section>주최자 액션...</section></>
) : (
  // 참여자 뷰 - isParticipant일 때만 표시
  // isParticipant: participants.some(p => p.userId === MOCK_USER_ID && p.role === 'participant')
  isParticipant && (
    <><Separator />
    <section className='space-y-3'>
      <div className='flex items-center gap-2 text-emerald-600'>
        <CheckCircle2 size={18} />
        <span className='text-sm font-medium'>참여 중인 이벤트입니다</span>
      </div>
      <Button variant='ghost' className='w-full text-destructive hover:text-destructive' disabled>
        <LogOut size={16} className='mr-2' />
        참여 취소
      </Button>
    </section></>
  )
)}

import에 CheckCircle2, LogOut 추가
isParticipant 변수 추가:
const isParticipant = participants.some(p => p.userId === MOCK_USER_ID && p.role === 'participant')
